<?php
require_once __DIR__ . '/includes/auth.php';
$message = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $email = filter_var(trim($_POST['email'] ?? ''), FILTER_VALIDATE_EMAIL); if ($email) { $token = bin2hex(random_bytes(32)); $statement = db()->prepare('UPDATE users SET reset_token = ?, reset_expires_at = DATE_ADD(NOW(), INTERVAL 1 HOUR) WHERE email = ?'); $statement->execute([$token, $email]); $message = 'Se o e-mail existir, um link de recuperação foi preparado. Em ambiente local, use o token abaixo: ' . $token; } else $message = 'Informe um e-mail válido.'; }
$pageTitle = 'Recuperar senha'; require __DIR__ . '/partials/header.php'; ?><div class="auth-shell"><div class="auth-brand"><span class="brand-mark">+</span><h1 class="page-title mt-3">Acesso de volta.</h1></div><div class="panel"><h2 class="h5">Recuperar senha</h2><p class="text-muted small">Digite o e-mail da sua conta.</p><?php if ($message): ?><div class="alert alert-info small"><?= e($message) ?></div><?php endif; ?><form method="post" data-validate novalidate><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><label class="form-label">E-mail</label><input class="form-control mb-3" type="email" name="email" required><button class="btn btn-primary w-100">Gerar recuperação</button></form><p class="text-center mt-4 mb-0 small"><a href="login.php">Voltar ao login</a></p></div></div><?php require __DIR__ . '/partials/footer.php'; ?>
